from dataclasses import dataclass


class InventoryError(Exception):
    pass


class UnknownProduct(InventoryError):
    def __init__(self, sku):
        super().__init__(f"unknown product: {sku}")
        self.sku = sku


class OutOfStock(InventoryError):
    def __init__(self, sku, available):
        super().__init__(f"only {available} of {sku} left")
        self.sku = sku
        self.available = available


@dataclass
class Product:
    sku: str
    name: str
    price_cents: int
    quantity: int = 0


class Inventory:
    def __init__(self):
        self._products = {}

    def add_product(self, product):
        if product.sku in self._products:
            raise ValueError(f"duplicate sku: {product.sku}")
        self._products[product.sku] = product

    def _get(self, sku):
        if sku not in self._products:
            raise UnknownProduct(sku)
        return self._products[sku]

    def restock(self, sku, amount):
        product = self._get(sku)
        if amount <= 0:
            raise ValueError("amount must be positive")
        product.quantity += amount

    def take(self, sku, amount):
        product = self._get(sku)
        if amount <= 0:
            raise ValueError("amount must be positive")
        if amount > product.quantity:
            raise OutOfStock(sku, product.quantity)
        product.quantity -= amount
        return product

    def __len__(self):
        return len(self._products)

    def __contains__(self, sku):
        return sku in self._products

    def __iter__(self):
        return iter(sorted(self._products.values(), key=lambda p: p.sku))

    @property
    def total_value(self):
        total = 0
        for p in self._products.values():
            total += p.price_cents * p.quantity
        return total

    def low_stock(self, threshold):
        skus = []
        for p in self:
            if p.quantity < threshold:
                skus.append(p.sku)
        return skus


def process_orders(inventory, orders):
    lines = []
    filled = 0
    for sku, amount in orders:
        try:
            inventory.take(sku, amount)
        except (InventoryError, ValueError) as e:
            lines.append(f"FAILED {sku} x{amount}: {e}")
        else:
            filled += 1
            lines.append(f"OK {sku} x{amount}")
    lines.append(f"{filled} of {len(orders)} orders filled")
    return lines
